style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://www.pinterest.com/pin/27443878977052211/"); /* replace with your uploaded image link */
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center top;
  }

  /* Make Roblox containers transparent so the background shows */
  .theme-container,
  .container,
  .content,
  .navbar,
  .footer,
  .root,
  #app,
  #container-main {
    background-color: transparent !important;
  }

  /* Optional: soften white boxes slightly */
  .game-card,
  .profile-container,
  .section-content {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 10px;
  }
}
